import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;

        long ans = 0;
        int last1 = 0; // posição do último destaque visto
        int prev1 = 0; // posição do destaque anterior ao último

        for (int i = 1; i <= n; i++) {
            in.nextToken();
            if (in.nval == 1.0) {
                // Seções terminando em i (que é destaque): l pode ser
                // qualquer posição depois do destaque anterior.
                prev1 = last1;
                last1 = i;
                ans += i - prev1;
            } else if (last1 > 0) {
                // Seções terminando em i (não destaque): o único destaque
                // dentro do intervalo deve ser o último visto (last1),
                // então l deve estar em (prev1, last1].
                ans += last1 - prev1;
            }
        }

        System.out.println(ans);
    }
}
